"use client";
import { createContext, useContext, type ComponentProps, type CSSProperties, type ReactNode } from "react";
import { Icon } from "./icon";
import { cn } from "./cn";
import { haptic } from "./haptics";

/**
 * Phone-only accordion for tiles. Provide this above a grid and every `Tile` inside
 * becomes collapsible. The library holds no state: `isOpen` and `toggle` are yours.
 */
export interface AccordionApi { scope: string; isOpen: (key: string, fallback: boolean) => boolean; toggle: (key: string, nextOpen: boolean) => void }
/** Provide this above a grid to make its tiles collapsible on a phone. */
export const AccordionContext = createContext<AccordionApi | null>(null);
const TileKey = createContext<{ key: string; open: boolean; api: AccordionApi } | null>(null);

type Vars = CSSProperties & Record<`--${string}`, string | number>;

export interface TileProps {
  /** A stable name for the tile: becomes its element id and its accordion key. */
  id: string;
  /** Column span on desktop. */
  cols?: number;
  /** Column span on a tablet. */
  colsTablet?: number;
  /** Column span on a phone. */
  colsMobile?: number;
  /** Row span. */
  rows?: number;
  /** Colour treatment: sage, clay, glow, deep, or hero. */
  tone?: string;
  className?: string;
  /** Skip the card chrome. Used for phone layouts that style themselves. */
  bare?: boolean;
  /** Inline styles, including `--custom` properties. */
  style?: Vars;
  /** Start expanded when inside an accordion. */
  defaultOpen?: boolean;
  children: ReactNode;
}

/** A card on the home grid: sized in columns and rows, tinted with `tone`, and (on a phone, inside an `AccordionContext`) collapsible. */
export function Tile({ id, cols = 4, colsTablet = 3, colsMobile = 6, rows = 2, tone, className, bare, style, defaultOpen, children }: TileProps) {
  const api = useContext(AccordionContext);
  const cls = cn(tone && (tone === "hero" ? "hero" : `t-${tone}`), tone === "deep" && "deep", className);
  if (bare) return <section className={cls} id={`t-${id}`} style={style}>{children}</section>;
  const vars: Vars = { "--c": cols, "--r": rows, "--ct": colsTablet, "--cm": colsMobile, ...style };
  const key = api ? `${api.scope}:t-${id}` : null;
  const open = key && api ? api.isOpen(key, !!defaultOpen) : false;
  return (
    <TileKey.Provider value={key && api ? { key, open, api } : null}>
      <section data-slot="tile" className={cn("tile", cls, key && "aacc", key && open && "open")} id={`t-${id}`} style={vars}>{children}</section>
    </TileKey.Provider>
  );
}

/** Tile header: title, optional eyebrow above it, optional trailing control. */
export function TileHeader({ title, eyebrow, right }: {
  /** The tile's heading. */
  title?: ReactNode;
  /** Small label above the title. */
  eyebrow?: ReactNode;
  /** A control at the end of the header. */
  right?: ReactNode;
}) {
  const acc = useContext(TileKey);
  const toggle = () => { haptic("select"); acc?.api.toggle(acc.key, !acc.open); };
  return (
    <div className="th" {...(acc ? { role: "button", tabIndex: 0, onClick: toggle, onKeyDown: (e: React.KeyboardEvent) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggle(); } } } : {})}>
      <div>
        {eyebrow ? <div className="eyebrow">{eyebrow}</div> : null}
        <h3>{title}</h3>
      </div>
      {right}
      {acc ? <Icon n="chev" c="sm accv" /> : null}
    </div>
  );
}

/** Auto-fitting 12-column bento grid. */
export function Grid({ className, ...rest }: ComponentProps<"div">) { return <div data-slot="grid" className={cn("grid", className)} {...rest} />; }

/* Tile, TileHeader, Grid and the tone classes. Moved out of globals.css; contextual overrides (.hero .btn, .pg3 .dt) stay with the screens that need them. */
.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));grid-auto-rows:minmax(86px,auto);gap:14px;grid-auto-flow:dense}
.tile{grid-column:span var(--c,4);grid-row:span var(--r,2);background:var(--tile);border-radius:var(--radius);padding:18px;box-shadow:var(--shadow);position:relative;min-width:0;display:flex;flex-direction:column;gap:12px;scroll-margin-top:90px}
.tile.flash{animation:flash 1.3s ease}
.th{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:28px}
.th h3,.tt{font:650 1.125rem/1.2 var(--f-display);font-stretch:92%;letter-spacing:-.01em}
.th .eyebrow{display:flex;align-items:center;gap:7px}
.t-deep{background:var(--deep);color:var(--deep-ink)}
.t-deep .eyebrow,.t-deep small,.t-deep .muted{color:var(--deep-ink2)}
.t-deep .btn{background:rgba(241,236,223,.12);color:var(--deep-ink)}
.t-deep .btn--p{background:var(--deep-ink);color:var(--deep)}
.t-clay,.t-glow,.t-sage{--tile2:var(--over)}
.t-clay{background:var(--clay-soft)}
.t-glow{background:var(--glow-soft)}
.t-sage{background:var(--sage-soft)}
.t-deep .pill{background:rgba(241,236,223,.12);color:var(--deep-ink)}
.t-deep .pill.warn{background:rgba(242,188,94,.18);color:var(--deep-warn)}
.t-deep .row+.row{border-top-color:var(--deep-line)}
.t-glow .is-on .dico{background:var(--over)}
@media (max-width:1100px){
  .grid{grid-template-columns:repeat(6,minmax(0,1fr))}
  .tile{grid-column:span var(--ct,3);grid-row:auto}
}
@media (max-width:620px){
  .tile{grid-column:span var(--cm,6);padding:16px}
}
@media (max-width:700px){
  .grid{grid-auto-rows:auto;gap:10px}
  .tile{gap:10px}
  .th .accv{margin-left:8px}
  .grid .tile[id^="t-h"] .th{flex-wrap:wrap}
  .grid .tile[id^="t-h"] .pill{white-space:normal}
}
